var keys = { left: false, right: false, run: false, jump: false };
var jumpJustPressed = false;
var enterPressed = false;

function clearInputEdges() {
  jumpJustPressed = false;
  enterPressed = false;
}

function keyJump(code) {
  return code === "Space" || code === "KeyW" || code === "KeyX" || code === "KeyZ";
}

document.addEventListener("keydown", function (e) {
  var c = e.code;
  if (c === "ArrowLeft" || c === "ArrowRight" || c === "ArrowUp" || c === "ArrowDown" || c === "Space") {
    e.preventDefault();
  }
  if (c === "ArrowLeft" || c === "KeyA") keys.left = true;
  else if (c === "ArrowRight" || c === "KeyD") keys.right = true;
  if (c === "ShiftLeft" || c === "ShiftRight" || c === "KeyZ") keys.run = true;
  if (keyJump(c)) {
    keys.jump = true;
    if (!e.repeat) jumpJustPressed = true;
  }
  if (c === "Enter" && !e.repeat) enterPressed = true;
});

document.addEventListener("keyup", function (e) {
  var c = e.code;
  if (c === "ArrowLeft" || c === "KeyA") keys.left = false;
  else if (c === "ArrowRight" || c === "KeyD") keys.right = false;
  if (c === "ShiftLeft" || c === "ShiftRight" || c === "KeyZ") keys.run = false;
  if (keyJump(c)) keys.jump = false;
});
